def testBuild() {
	TIME_LIMIT = params.TIME_LIMIT ? params.TIME_LIMIT.toInteger() : 10
	timeout(time: TIME_LIMIT, unit: 'HOURS') {
		boolean runMulticastCmd = false

		if (JOB_NAME.contains("special.jck") || JOB_NAME.contains("extended.openjdk") || TARGET == "special.jck" || TARGET == "extended.openjdk" || TARGET.contains("_nio") || TARGET.contains("_net") || TARGET.contains("_custom")) {
			// only enable on linux based platforms atm
			if (PLATFORM.contains('linux')) {
				def statusCode =  sh returnStatus: true, script: """
					which activate_multicast
					"""
					echo "which activate_multicast status code: ${statusCode}"
				if (statusCode == 0) {
					runMulticastCmd = true
				}
			}
		}
		echo "runMulticastCmd: ${runMulticastCmd}"
		try {
			addJobDescription()
			setup()
			addGrinderLink()

			if (runMulticastCmd) {
				echo "sudo activate_multicast"
				sh "sudo activate_multicast"
			}
			// prepare environment and compile test projects
			if ((env.PARALLEL == "NodesByIterations" && NUM_MACHINES > 1)
				|| (env.PARALLEL == "Dynamic" && (NUM_MACHINES > 1 || (params.TEST_TIME && !params.NUM_MACHINES)))) {
				if (setupParallelEnv() == 1) {
					// Fall back to non-parallel.
					env.PARALLEL = 'None'
					testExecution()
				}
			} else {
				env.PARALLEL = 'None'
				testExecution()
			}
		} finally {
			// Terminate any left over test job processes
			terminateTestProcesses()

			if (runMulticastCmd) {
				echo "sudo deactivate_multicast"
				sh "sudo deactivate_multicast"
			}

			if (!params.KEEP_WORKSPACE) {
				forceCleanWS()
				// clean up remaining core files
				if (PLATFORM.contains("mac")) {
					sh "find /cores -name '*core*' -print 2>/dev/null -exec rm -f {} \\; || true"
				} else if (PLATFORM.contains("windows")) {
					sh "find /cygdrive/c/temp -name '*core*' -print 2>/dev/null -exec rm -f {} \\; || true"
				} else {
					sh "find /tmp -name '*core*' -print 2>/dev/null -exec rm -f {} \\; || true"
				}
			}
		}
	}
}

