def mergeTestCasesWithoutDup(String knownTestCases, String newTestCases) {
	if (knownTestCases) {
		def knownTestCasesList = knownTestCases.split(/\s+/)
		def newTestCasesList = newTestCases.split(/\s+/)
		def filterednewTestCases = newTestCasesList.findAll { !(it in knownTestCasesList) }
		return ( knownTestCases + " " + filterednewTestCases.join(" "))
	} else {
		return newTestCases
	}
}

def addFailedTestsGrinderLink(paths="") {
	if (env.jobStatus == 'UNSTABLE' || env.jobStatus == 'FAILURE' || env.jobStatus == 'ABORTED') {
		def customizedTestCases = getFailedAndCustomizedTest(paths)
		String url = env.RERUN_LINK
		// Add rerun FailedTests link only if there are targets other than _custom as it's duplicate with rerun customized link
		if (env.FAILED_TESTS?.trim() && (env.FAILED_TESTS.contains(',') || !env.FAILED_TESTS.contains('_custom'))) {
			// Remove _custom target from FAILED_TESTS
			def filteredFailedTestLists = env.FAILED_TESTS.split(',').collect{ it.trim() }.findAll { !it.contains('_custom') }.join(',')
			String failedTestList = "testList+TESTLIST=" + filteredFailedTestLists
			def failedTestUrl = url.replace(env.FAILED_TEST_TARGET, "TARGET=$failedTestList")
			echo "Rerun in Grinder with failed test targets: ${failedTestUrl}"
			currentBuild.description += "<br><a href=${failedTestUrl}> Rerun in Grinder with failed test targets</a>"
		}
		if ( customizedTestCases != null ) {
			customizedTestCases.each { target, testcases ->
				def tempTestCases = testcases
				tempTestCases = URLEncoder.encode(tempTestCases.toString(), "UTF-8")
				def customURL = url.replace(env.FAILED_TEST_TARGET, "TARGET=${target}_custom")
				customURL = customURL.replace(env.CUSTOM_TARGET_KEY_VALUE, "CUSTOM_TARGET=$tempTestCases")
				echo "Rerun failed ${target} test cases in Grinder with ${target}_custom target: ${customURL}"
				currentBuild.description += "<br><a href=${customURL}> Rerun failed ${target} test cases in Grinder with ${target}_custom target</a>"
			}
		}
	}
}

