// update to return worst child job status, and failure test job parameters.
def archiveChildJobTap(childJobs, originalStatus = 'SUCCESS') {
	node (env.SETUP_LABEL) {
		def childTestJobParams = [:]
		def currentStatus = 'SUCCESS';
		forceCleanWS()
		try {
			def buildPaths = ""
			def childJobStatus = "<table><tr><th>Child Job</th><th>Status</th><th>Duration</th></tr>"
			def jobList = childJobs.values().toList()
			sortByProjectName(jobList)
			jobList.each {
				cjob ->
					def jobInvocation = cjob.getRawBuild()
					def buildId = jobInvocation.getNumber()
					def name = cjob.getProjectName()
					def childResult = cjob.getCurrentResult()
					echo "${name} #${buildId} completed with status ${childResult}"
					// track FAILURE job childTestJobParams if it's rerun stage
					if ( originalStatus == "SUCCESS" && childResult == "FAILURE" ) { 
						childTestJobParams << parallelTestParams.findAll {it.key == name}
					}
					if (isWorseThan( childResult, currentStatus)) {
						currentStatus = childResult
					}
					try {
						timeout(time: 1, unit: 'HOURS') {
							copyArtifacts (projectName: "${name}", selector: specific("${buildId}"), filter: "**/*.tap", target:"${name}/${buildId}")
						}
						archiveFile("${name}/${buildId}/**/*.tap", true)
						buildPaths += "${name}/${buildId}/,"
					} catch (Exception e) {
						echo 'Exception: ' + e.toString()
						echo "Cannot copy *.tap or AQACert.log from ${name} with buildid ${buildId} . Skipping copyArtifacts..."
					}
					def childBuildUrl = "${env.JENKINS_URL}job/${name}/${buildId}"
					def badgeUrl = "${childBuildUrl}/badge/icon"
					def duration = cjob.getDuration() ?: ""
					if (duration) {
						long totalMillis = duration as long
						def hours = ((int)(totalMillis / (1000 * 60 * 60))) % 24
						def minutes = ((int)(totalMillis / (1000 * 60))) % 60
						def seconds = ((int)(totalMillis / 1000)) % 60
						duration = "${hours}h ${minutes}m ${seconds}s"
					}
					childJobStatus += """
						<tr>
							<td>${name}/${buildId}</td>
							<td><a href="${childBuildUrl}"><img src="${badgeUrl}" /></a></td>
							<td>${duration}</td>
						</tr>
					"""
			}
			childJobStatus += "</table>"
			currentBuild.description = (currentBuild.description) ? currentBuild.description + "<br>" + childJobStatus : childJobStatus

			// In case rerun job status be worse than original job status
			if ( originalStatus != "SUCCESS" && isWorseThan( currentStatus, originalStatus)) {
				currentStatus = originalStatus
			}

			archiveAQAvitFiles()
			env.jobStatus = currentStatus
			if (currentStatus != "SUCCESS") {
				if ( buildPaths!= "" ) {
					if ( originalStatus == "SUCCESS" ) {
						getFailedAndCustomizedTest(buildPaths[0..-2])
					} else {
						addFailedTestsGrinderLink(buildPaths[0..-2])
					}
				} else if (env.PARALLEL == 'None') {
					try {
						timeout(time: 1, unit: 'HOURS') {
							copyArtifacts (projectName: "${env.JOB_NAME}", selector: specific("${env.BUILD_NUMBER}"), filter: "**/*.tap")
						}
					} catch (Exception e) {
						echo 'Exception: ' + e.toString()
						echo "Cannot copy *.tap from ${env.JOB_NAME} with buildid ${env.BUILD_NUMBER} . Skipping copyArtifacts..."
					}
					addFailedTestsGrinderLink()
				}
			}
		} finally {
			forceCleanWS()
		}
		return [jobStatus: currentStatus, jobParams: childTestJobParams]
	}
}

