def isWorseThan(String resultA, String resultB) {
	def severityOrder = [ 'SUCCESS', 'UNSTABLE', 'FAILURE', 'ABORTED']
	def indexA = severityOrder.indexOf(resultA)
	def indexB = severityOrder.indexOf(resultB)
	return indexA > indexB
}

def runParallelTests() {
	def parallelResults = [:]
	if (env.PARALLEL != "None" && (NUM_MACHINES > 1 || params.TEST_TIME)) {
		stage ("Parallel Tests") {
			def childJobs = parallel parallel_tests
			// There are cases env.PARALLEL != "None", but job is non parallel if number list is 1
			if ( !childJobs.isEmpty() ) { 
				parallelResults = archiveChildJobTap(childJobs) 
			}
		}
	}
	return parallelResults
}

def getGitRepoBranch(ownerBranch, defaultOwnerBranch, repo) {
	String[] actualRepoBranch = defaultOwnerBranch.split(":")
	if (ownerBranch) {
		String[] tokens = ownerBranch.split(":")
		if (tokens.size() == 2 ) {
			actualRepoBranch = tokens;
		} else {
			error "[ERROR]: Wrong format of XXX_OWNER_BRANCH value: ${ownerBranch}. The expected format is [owner]:[branch]"
		}
	}

	String owner = actualRepoBranch[0].trim()
	String repoURL = "https://github.com/${owner}/${repo}.git"
	if (env.SPEC.startsWith('zos')) {
		repoURL = repoURL.replace("https://github.com/","git@github.com:")
	}
	actualRepoBranch[0] = repoURL
	actualRepoBranch[1] = actualRepoBranch[1].trim()
	return actualRepoBranch
}

def forceCleanWS() {
	def retry_count = 0
	def max_retries = 3
	def sleep_time = 30
	retry(max_retries) {
		try {
			if (retry_count > 0) {
				echo "Retrying cleanWs attempt ${retry_count + 1}/${max_retries} after ${sleep_time} seconds sleep..."
				sleep(sleep_time)
			}
			retry_count++
			cleanWs disableDeferredWipeout: true, deleteDirs: true
		} catch (Exception e) {
			echo 'Exception: ' + e.toString()
			//cleanWs has issue to delete workspace that contains non-ASCII filename in TKG output https://issues.jenkins.io/browse/JENKINS-33478
			//cannot delete workspace directly. Otherwise, Jenkins job will abort due to missing workspace
			dir (env.WORKSPACE) {
				echo "Force clean Workspace at $pwd"
				sh "rm -rf aqa-tests/TKG"
			}
			// call cleanWs() again
			cleanWs disableDeferredWipeout: true, deleteDirs: true
		}
	}
}

def checkDacapoH2Metric() {
        def regex = ".*=====\\sDaCapo.*?h2\\sPASSED\\sin\\s(\\d*\\.?\\d*)\\smsec\\s=====\\s*\$"
        def matcher = manager.getLogMatcher(regex)  

        if (matcher?.matches()) {
                def runtime = matcher.group(1) 
                archiveDacapoH2Metric(runtime)
                println("DaCapo-h2 metric found and archived")
        } else {
                println("no DaCapo-h2 metric found")
        }
}

def archiveDacapoH2Metric(runtime) {
        def fileName = "${env.JOB_NAME}_${env.BUILD_NUMBER}.json"
        def jsonData = [
                "benchmark": "dacapo-h2", 
                        "metrics": [
                                "dacapo-h2": [
                                        ["value": runtime],
                                        ["higherbetter": true], 
                                        ["units": "msec"]
                                ]
                        ]
        ]
        writeJSON file: fileName, json: jsonData
        archiveArtifacts artifacts: fileName, fingerprint: true, allowEmptyArchive: false
}

return this

