                if (("${TARGET}".contains('functional')) || ("${TARGET}".contains('external'))) {
                    DYNAMIC_COMPILE = true
                } else {
                    DYNAMIC_COMPILE = false
                }
            } else {
                DYNAMIC_COMPILE = params.DYNAMIC_COMPILE ? params.DYNAMIC_COMPILE.toBoolean() : false
            }

