                    }
                    if (cmd) {
                        build job: 'all-nodes-matching-labels', parameters: [
                            string(name: 'LABEL', value: label),
                            string(name: 'COMMAND', value: cmd),
                            string(name: 'TIMEOUT_TIME', value: '48')
                        ], propagate: true
                    }
                }
            }
        }
        parallel parallelJobs
    }
}

