				}

				if (params.PLATFORMS) {
					PLATFORMS = PLATFORMS.split(',')
				} else {
					PLATFORMS = [
						"arm_linux",
						"aarch64_linux",
						"aarch64_linux_xl",
						"ppc32_aix",
						"ppc32_linux",
						"ppc64_aix",
						"ppc64_aix_xl",
						"ppc64_linux",
						"ppc64_linux_xl",
						"ppc64le_linux",
						"ppc64le_linux_xl",
						"riscv64_linux",
						"riscv64_linux_xl",
						"s390_linux",
						"s390_zos",
						"s390x_linux",
						"s390x_linux_xl",
						"s390x_zos",
						"s390x_zos_xl",
