# limitations under the License.
################################################################################

undef @out;
$_ = <>;
chomp;
$_=(split(/:/,$_))[0];
@b = split(/\./,$_);
splice(@b,1,0,"") if $#b == 1;
$min = $b[2];
$max = $b[2];
$b[2]+=1;
while(<>) {
  chomp;
  $_=(split(/:/,$_))[0];
  @a = split(/\./,$_);
  splice(@a,1,0,"") if $#a == 1;
  if (join('.',@a) eq join('.',@b)) {
    $max+=1;
  } else {
    push @out,"$b[1]:$min..$max";
    $min=$a[2];
    $max=$a[2];
  }
  $a[2]+=1;
  @b=@a;
}
push @out,"$b[1]:$min..$max";
print join(',',@out)."\n";

