private static boolean compareResult(String[] l1, String[] l2) {
        boolean result = true;
        int len1 = l1.length;
        int len2 = l2.length;
        int i = 0;
        for (; i < Math.min(len1, len2); i++) {
            if (!l1[i].equals(l2[i])) {
                System.err.println(i+"< "+l1[i]);
                System.err.println(i+"> "+l2[i]);
                result = false;
            }
        }
        if (len1 > len2) {
            result = false;
            for (; i < len1; i++) {
                System.err.println(i+"< "+l1[i]);
            }
        } else if (len1 < len2) {
            result = false;
            for (; i < len2; i++) {
                System.err.println(i+"> "+l2[i]);
            }
        }
        return result;
    }
}

