################################################################################
BASE=`dirname $0`
OS=`uname`
LOC=`locale charmap`
FULLLANG=${OS}_${LANG%.*}.${LOC}

. ${BASE}/check_env_unix.sh

if [ "${BASE}" != "${PWD}" ]; then
  cp ${BASE}/*.java .
fi

CP="-cp ${BASE}/annotation.jar"

TS=`${JAVA_BIN}/java ${JAVA_OPTIONS} ${CP} CheckValidData "${TEST_STRINGS}"`

echo "creating source file..."
# sed "s/TEST_STRING/${TS}/g" DefineAnnotation_org.java > DefineAnnotation.java
cat > DefineAnnotation.java <<EOF
@interface ${TS}
{
    String ${TS}_2();
    int ${TS}_1();
}
@interface ${TS}_constructor
{
    String value();
}
@interface ${TS}_method
{
    String value();
}
@interface ${TS}_field
{
    String value();
}
EOF

#sed "s/TEST_STRING/${TS}/g"  AnnotatedTest_org.java >  AnnotatedTest.java
cat > AnnotatedTest.java <<EOF
@${TS}(
    ${TS}_1 = 1234567890,
    ${TS}_2 = "${TS}"
)
public class AnnotatedTest{
    @${TS}_constructor("${TS}") 
        public AnnotatedTest(){
    }
    // Annotated Methods
    @${TS}_method("${TS}_1") 
    public void ${TS}_1(){}
    @${TS}_method("${TS}_2")
    public  void ${TS}_2(){}
    // Annotated Fields
    @${TS}_field("${TS}_1") 
    public String ${TS}_1 = "${TS}";
    @${TS}_field("${TS}_2")
    public int ${TS}_2 = 0;
}
EOF

SDKPATH=`${JAVA_BIN}/java ${CP} SDKPath`

echo "compiling..."
${SDKPATH}/javac ${JAVAC_OPTIONS} DefineAnnotation.java AnnotatedTest.java

echo "execute javap"
${SDKPATH}/javap ${JAVAC_OPTIONS} AnnotatedTest > javap.txt 2>&1
diff javap.txt ${BASE}/expected/${FULLLANG}.def.txt > diff.txt

${SDKPATH}/java ${JAVA_OPTIONS} ${CP} SourceVersionCheck ${BASE}/expected/${FULLLANG}.pro.txt 2>> diff.txt

#clean up
rm *.class

if [ -s diff.txt ]
then
  # failed
  exit 1
else
  # passed
  exit 0
fi

