                        charName = "BEL";
                    }else if (codePointStart == 0x80){
                        charName = "PADDING CHARACTER";
                    }else if (codePointStart == 0x81){
                        charName = "HIGH OCTET PRESET";
                    }else if (codePointStart == 0x99){
                        charName = "SINGLE GRAPHIC CHARACTER INTRODUCER";
