		"       s"+i+" = true;\n"+
		"	//System.out.println(\"closing "+testStrings[i]+"\");\n"+
		"    }\n"+
		"  }\n"
		);
	    }
		builder.append(
		"  public "+className+"() {\n"+
		"    boolean flag = false;\n"+
		"    try(\n"
		);
	    for (int i=0; i< testStrings.length-1; i++) {
	        builder.append(
		"     "+testStrings[i]+" s"+i+" = new "+testStrings[i]+"();\n"
		);
