        assertEquals("1 01 Q1 1st quarter 1", str);

        str = date.format(DateTimeFormatter.ofPattern(
                            "q qq qqq qqqq qqqqq",
                            Locale.US));
        assertEquals("1 01 Q1 1st quarter 1", str);
    }

    @Test
