            assertEquals(data.era.getValue(), dateH.getLong(ChronoField.ERA));
            assertEquals(data.eraYear, dateH.getLong(ChronoField.YEAR_OF_ERA));
            assertEquals(data.year, dateH.getLong(ChronoField.YEAR));
