	  fo.delete(dst);
	  System.out.println("Deleted Directory :");
	  fo.list(dst, 3);
	  break;

	case 'L':
	  fo.list(src, 3);
	  break;
	}

    } catch (java.io.IOException e) {
      e.printStackTrace();
    }
  }

