	 * 
	 * @param mean
	 * @param radius
	 * @return
	 */
	public static double generateRandomTime(double mean, double radius)
	{	
		if (radius == 0)
			return mean; 

		do 
		{
			// Generate a lifespan 
			double candidateLifespan = (randomInstance.nextDouble() * (radius * 2)) + (mean - radius);

			// If it fits in the radius, return it. Otherwise, try again. 
			if (
				   candidateLifespan > 0 
