		getElement().setDefaultForAttribute("startTime", "0", null);
		getElement().assertAttributeIsSet("duration");
		getElement().assertAttributeIsSet("numThreads");

		duration = parseTimeField("duration");
		startTime = parseTimeField("startTime");
