	 * Enables updates to the status output.  
	 * 
	 * @param mainShutdownMutex
	 */
	protected void enableStatus(AtomicMutex mainShutdownMutex)
	{		
		if (!isFinished())				
			statusInhibitMutex.release();							
	}

