public static void validate(String xml) throws Exception {
        System.err.println("Checking: " + xml);
        wellFormed(xml);
        validByXsd(xml);
    }

    public static void wellFormed(String xml) throws ParserConfigurationException, SAXException, IOException {
        System.err.println("Well formed?");
        DocumentBuilderFactory factory = DocumentBuilderFactory.newInstance();
        factory.setValidating(false);
        factory.setNamespaceAware(true);
        DocumentBuilder builder = factory.newDocumentBuilder();
        Document document = builder.parse(new InputSource(xml));
        System.err.println("Well formed!");
    }

    public static void validByXsd(String xml) throws ParserConfigurationException, SAXException, IOException {
        String url = "https://raw.githubusercontent.com/adoptium/TKG/master/resources/playlist.xsd";
        System.err.println("Valid by " + url + " ?");
        SchemaFactory factory = SchemaFactory.newInstance(XMLConstants.W3C_XML_SCHEMA_NS_URI);
        Schema schema = factory.newSchema(new URL(url));
        Validator validator = schema.newValidator();
        validator.validate(new StreamSource(new File(xml)));
        System.err.println("Valid!");
    }

    private enum OutputType {
        GENERATE, DO, TEST, STATS, REGEXES, VALIDATE
    }

    private interface TestDetails {
        int getMainOne();

        int getAll();

        void add(Object testDetails);

    }

    private static class GroupWithCases implements Comparable<GroupWithCases> {
        final String name;
        String regex;
        TestDetails tests;
        int classes;

        public GroupWithCases(String name, boolean clazz) throws Exception {
            this(name, name, clazz);
        }

        public GroupWithCases(String name, String regex, boolean clazz) throws Exception {
            this.name = name;
            if (clazz) {
                if (parseUseFQN()) {
                    this.regex = regex;
                } else {
                    this.regex = regex.replace("org.openjdk.jcstress.", "");
                }
            } else {
                this.regex = regex;
            }
            if (clazz) {
                String innerGroup = name;
                while (true) {
                    try {
                        tests = getJcstressTests(innerGroup);
                        classes = 1;
                        break;
                    } catch (ClassNotFoundException ex) {
                        innerGroup = replaceLast(innerGroup, "\\.", "$");
                        if (!innerGroup.contains(".")) {
                            throw ex;
                        }
                    }
                }
            } else {
                tests = new ActorArbiter(0, 0);
                classes = 0;
            }
        }

        public GroupWithCases(String name, String regex, TestDetails testDetails, int classes) {
            this.name = name;
            this.regex = regex;
            this.tests = testDetails;
            this.classes = classes;
        }

        private String replaceLast(String string, String what, String by) {
            String reverse = new StringBuffer(string).reverse().toString();
            Matcher matcher = Pattern.compile(what).matcher(reverse);
            reverse = matcher.replaceFirst(matcher.quoteReplacement(by));
            string = new StringBuffer(reverse).reverse().toString();
            return string;
        }

        @Override
        public boolean equals(Object o) {
            if (this == o) return true;
            if (o == null || getClass() != o.getClass()) return false;
            GroupWithCases that = (GroupWithCases) o;
            return Objects.equals(name, that.name);
        }

        @Override
        public int hashCode() {
            return Objects.hash(name);
        }

